create unique index if not exists sales_user_external_unique on public.sales(user_id, external_id) where external_id is not null; create unique index if not exists sales_user_transaction_unique on public.sales(user_id, transaction_id) where transaction_id is not null; create index if not exists gateway_transactions_user_idempotency_idx on public.gateway_transactions(user_id, idempotency_key) where idempotency_key is not null;